         opens_invariants none
         no_unwind
     )]
     fn drop(&mut self) {
         if let Err(e) = super::frame::free(self.base) {
             #[cfg(not(verus_keep_ghost))]
             error!("failed to free kernel frame: {:?}", e);
         }
     }
 }

